{"path": "textutils.py", "content": "import re
from collections import Counter

_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Map lower-cased words to their counts, ignoring punctuation.

    Words are runs of letters, digits and apostrophes; apostrophes at the
    start or end of a run (quote marks) are dropped.
    """
    counts = Counter()
    for match in _WORD_RE.findall(text.lower()):
        word = match.strip("'")
        if word:
            counts[word] += 1
    return dict(counts)
"}

