from textutils import words, word_count


class T(unittest.TestCase):
    def test_words(self):
        self.assertEqual(words('a b'), ['a', 'b'])

    def test_word_count(self):
        self.assertEqual(
            word_count("Hello, hello! It's 2 o'clock... HELLO?"),
            {'hello': 3, "it's": 1, '2': 1, "o'clock": 1},
        )

    def test_word_count_quotes_and_empty(self):
        self.assertEqual(word_count("'Hi' -- ' hi_there"), {'hi': 2, 'there': 1})
        self.assertEqual(word_count(''), {})
"}

